CREATE OR REPLACE FUNCTION public.icash_next_acquisition()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;j uuid;t public.icash_automation_tickets;backlog integer;allowance bigint;minimum_quote bigint;
begin
 perform 1 from public.icash_operating_budget where id=1 and enabled for update;
 if not found then return null;end if;
 perform public.icash_settle_pending_dealmachine();
 -- Expiry/exhaustion is terminal only for this exact proven-unstarted family.
 update public.icash_automation_tickets retry_ticket set outcome=case when owner_preview_deferrals>=8 then 'owner_preview_retry_exhausted' else 'owner_preview_expired' end
 where retry_ticket.kind='contacts' and retry_ticket.state='held' and retry_ticket.outcome='owner_preview_rate_limited'
 and (retry_ticket.owner_preview_deferrals>=8 or retry_ticket.owner_preview_retry_until<=clock_timestamp())
 and public.icash_owner_enrichment_unstarted(retry_ticket.account_id,retry_ticket.screening_id,'owners:'||retry_ticket.account_id||':'||retry_ticket.screening_id);
 update public.icash_automation_tickets set state='held',outcome='expired' where kind in ('contacts','discovery') and state='issued' and expires_at<=now();
 -- Leave other scheduler work available; billing and expiry checks above still run.

 for c in select d.* from public.icash_discovery_configs d join public.icash_accounts a on a.id=d.account_id join public.icash_wallets w on w.account_id=a.id
 where d.enabled and d.auto_enabled and d.next_run_at<=now() and public.icash_dealmachine_capacity_available(2,d.account_id) and d.data_rights_until>now() and not a.bot_paused and w.balance_cents>w.reserved_cents
 and not exists(select 1 from public.icash_automation_tickets x where x.account_id=a.id and ((x.state='issued' and x.expires_at>now()) or (x.state='consumed' and x.created_at>now()-interval '5 minutes')))
 order by
  -- Ordinary overdue accounts retain an aging escape from the due-list queue.
  case when d.next_run_at<now()-interval '10 minutes' then d.next_run_at end nulls last,
  public.icash_new_user_request_reserve_eligible(d.account_id) desc,
  case when d.contacts_enabled and d.contact_rate_id is not null
   and public.icash_owner_active_export_capacity(d.account_id) in ('disabled','ready')
   then public.icash_owner_preflight_due_at(d.account_id,null::uuid) end nulls last,
  case when d.contacts_enabled and d.contact_rate_id is not null
   and public.icash_owner_active_export_capacity(d.account_id) in ('disabled','ready')
   then public.icash_owner_retry_due_at(d.account_id) end nulls last,
  (d.next_run_at<now()-interval '5 minutes') desc,
  case when d.next_run_at<now()-interval '5 minutes' then d.next_run_at end,
  coalesce((public.icash_daily_work_target(d.account_id)->>'priorityRatio')::numeric,1),
  d.next_run_at,d.account_id limit 5 for update of d skip locked loop
 perform public.icash_prepare_research_efficiency(c.account_id);
 select * into c from public.icash_discovery_configs where account_id=c.account_id;
 perform public.icash_refresh_opportunity_outcomes(c.account_id);
 allowance:=public.icash_prospecting_available(c.account_id);
 select min(quote) into minimum_quote from (
  select public.icash_research_admission_quote(c.account_id,'property_search',r.charge_cents) quote
   from public.icash_operation_rates r where r.id=c.rate_id
  union all
  select public.icash_research_admission_quote(c.account_id,'owner_enrichment',r.charge_cents)
   from public.icash_operation_rates r where c.contacts_enabled and public.icash_owner_active_export_capacity(c.account_id) in ('disabled','ready') and r.id=c.contact_rate_id
 ) quotes;
 if minimum_quote is null or allowance<minimum_quote then
  update public.icash_discovery_configs set next_run_at=now()+interval '60 seconds' where account_id=c.account_id;
  continue;
 end if;
 j:=null;
 if c.contacts_enabled and c.contact_rate_id is not null then j:=public.icash_enrichment_candidate(c.account_id);end if;
 if j is not null then
 update public.icash_discovery_configs set next_run_at=now()+interval '5 seconds' where account_id=c.account_id;
 insert into public.icash_automation_tickets(account_id,kind,screening_id) values(c.account_id,'contacts',j)
 on conflict(screening_id) do update set token=gen_random_uuid()::text||gen_random_uuid()::text,state='issued',outcome=null,completed_at=null,created_at=now(),expires_at=least(now()+interval '2 minutes',coalesce(public.icash_automation_tickets.owner_preview_retry_until,now()+interval '2 minutes')),issue_attempts=case when public.icash_automation_tickets.outcome='owner_preview_rate_limited' then public.icash_automation_tickets.issue_attempts else public.icash_automation_tickets.issue_attempts+1 end
 returning * into t;
 return jsonb_build_object('token',t.token);
 end if;
 -- Provider capacity remains bounded while completed attempts free the queue.
 backlog:=public.icash_pending_opportunity_count(c.account_id);
 if c.exhausted or backlog>=c.max_open_prospects or not public.icash_outbound_search_due(c.account_id) then
  update public.icash_discovery_configs set next_run_at=now()+interval '60 seconds' where account_id=c.account_id;
  continue;
 end if;
 update public.icash_discovery_configs set next_run_at=now()+interval '5 seconds' where account_id=c.account_id;
 insert into public.icash_automation_tickets(account_id,kind) values(c.account_id,'discovery') returning * into t;
 return jsonb_build_object('token',t.token);
 end loop;
 return null;
end $function$

CREATE OR REPLACE FUNCTION public.icash_issue_account_followup()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare q icash_work_private.account_followups;t public.icash_automation_tickets;stamp timestamptz:=clock_timestamp();
begin
 -- A provider action may outlive a failed primary-finish transaction. Discover
 -- missing accounts from durable outstanding operations, bounded once a minute.
 update icash_work_private.dispatch_policy set last_seed_at=stamp
  where id=1 and (last_seed_at is null or last_seed_at<stamp-interval '1 minute');
 if found then
  insert into icash_work_private.account_followups(account_id)
   select distinct o.account_id from public.icash_operation_spend o
   where o.state in ('reserved','dispatched') and not exists(
    select 1 from icash_work_private.account_followups existing where existing.account_id=o.account_id)
   order by o.account_id limit 10 on conflict(account_id) do nothing;
 end if;
 select f.* into q from icash_work_private.account_followups f join public.icash_accounts recovery_account on recovery_account.id=f.account_id
 where f.next_run_at<=stamp and (f.lease_until is null or f.lease_until<=stamp)
  and (f.requested_version>f.completed_version or exists(
   select 1 from public.icash_operation_spend o where o.account_id=f.account_id and o.state in ('reserved','dispatched')))
 order by f.next_run_at,f.account_id for key share of recovery_account skip locked for update of f skip locked limit 1;
 if not found then return null;end if;
 -- Only idempotent receipt/notification recovery gets a fresh capability after
 -- a crashed handler. This does not rearm any primary call, text or purchase.
 if q.ticket_id is not null then
  update public.icash_automation_tickets set state='held',outcome='reconciliation_lease_expired',completed_at=stamp
   where id=q.ticket_id and account_id=q.account_id and kind='account_reconcile' and state in ('issued','consumed');
 end if;
 insert into public.icash_automation_tickets(account_id,kind) values(q.account_id,'account_reconcile') returning * into t;
 update icash_work_private.account_followups set ticket_id=t.id,lease_until=stamp+interval '5 minutes',
  claimed_version=requested_version,claimed_notify_version=notify_version,updated_at=stamp where account_id=q.account_id;
 return jsonb_build_object('token',t.token);
end $function$

CREATE OR REPLACE FUNCTION public.icash_settle_pending_estimates(p_account uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare o record;finished integer:=0;held integer:=0;
begin
 if p_limit not between 1 and 100 then raise exception 'Invalid batch';end if;
 for o in select s.operation_key from public.icash_operation_spend s where s.state='dispatched' and (p_account is null or s.account_id=p_account) and exists(select 1 from public.icash_operation_rates r where r.id=s.rate_id and r.operation not in ('seller_call','buyer_call','incoming_call')) order by s.estimate_checked_at nulls first,s.dispatched_at limit p_limit loop
 begin
 if public.icash_settle_estimated_operation(o.operation_key) then finished:=finished+1;else held:=held+1;end if;
 exception when others then held:=held+1;
 end;
 update public.icash_operation_spend set estimate_checked_at=now() where operation_key=o.operation_key;
 end loop;
 return jsonb_build_object('settled',finished,'held',held,'costBasis','estimated');
end $function$

CREATE OR REPLACE FUNCTION public.icash_settle_estimate_before_sms_tokens(p_operation text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare o public.icash_operation_spend;r public.icash_operation_rates;parts jsonb;proof boolean;charge bigint;total numeric;required numeric;evidence text;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 select * into o from public.icash_operation_spend where operation_key=p_operation for update;
 if not found then return false;end if;
 if o.state='settled' then return true;end if;
 if o.state<>'dispatched' then return false;end if;
 select * into strict r from public.icash_operation_rates where id=o.rate_id;
 -- Research must use the original observed credit receipt and saved multipliers.
 -- The maintenance path can race the provider handler after receipt persistence.
 if r.operation in ('property_search','owner_enrichment','buyer_discovery') then
  return public.icash_settle_dealmachine_usage(p_operation);
 end if;
-- A full-call quote is a reservation ceiling, never completed-call usage.
 if r.operation in ('seller_call','buyer_call','incoming_call') then return false;end if;
 proof:=exists(select 1 from public.icash_discovery_results where operation_key=o.operation_key and account_id=o.account_id)
 or exists(select 1 from public.icash_owner_contacts where operation_key=o.operation_key and account_id=o.account_id)
 or exists(select 1 from public.icash_buyer_search_receipts b join public.icash_deal_files d on d.id=b.deal_id where b.operation_key=o.operation_key and d.account_id=o.account_id)
 or exists(select 1 from public.icash_text_messages where 'text:'||id=o.operation_key and account_id=o.account_id and provider_id is not null and state in ('accepted','delivered'))
 or exists(select 1 from public.icash_text_ai_jobs where 'sms-ai:'||id=o.operation_key and account_id=o.account_id and provider_id is not null and usage is not null and state in ('drafted','queued','handoff','superseded'))
 or exists(select 1 from public.icash_deal_emails where 'deal-email:'||id=o.operation_key and account_id=o.account_id and provider_id is not null and state='accepted')
 or exists(select 1 from public.icash_title_requests where 'title:'||id=o.operation_key and account_id=o.account_id and provider_id is not null and state='sent')
 or exists(select 1 from public.icash_title_tasks where 'title-followup:'||id=o.operation_key and account_id=o.account_id and email_provider_id is not null and email_state='sent')
 or exists(select 1 from public.icash_title_qualification_jobs where 'title-qualify:'||id=o.operation_key and account_id=o.account_id and provider_id is not null and state='sent')
 or exists(select 1 from public.icash_signing_envelopes where 'signing:'||id=o.operation_key and account_id=o.account_id and provider_id is not null and not test_mode and state in ('awaiting_counterparty','customer_signature_needed','completed'))
 or exists(select 1 from public.icash_live_conversations where operation_key=o.operation_key and account_id=o.account_id and state='complete' and completed_at is not null);
 if not proof then return false;end if;
 evidence:='ESTIMATE: configured rate '||r.version||'; provider invoice costs not verified';
 select jsonb_object_agg(key,jsonb_build_object('amountMicros',value,'evidenceRef',evidence)),sum(value::text::numeric) into parts,total from jsonb_each(r.costs_micros);
 required:=total*o.standard_cost_multiplier-coalesce((r.costs_micros->>'elevenlabs')::numeric,0)*(o.standard_cost_multiplier-o.elevenlabs_cost_multiplier);
 charge:=ceil(required/10000);
 if charge>o.charge_cap_cents then return false;end if;
 -- The existing atomic ledger enforces reservations, fractional pricing, and margin checks.
 perform public.icash_settle_complete_costs(o.operation_key,charge,parts,evidence);
 update public.icash_operation_spend set cost_basis='estimated' where operation_key=o.operation_key;
 return true;
end $function$

CREATE OR REPLACE FUNCTION icash_work_private.enqueue_account_followup()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare changed boolean;
begin
 if old.state<>'consumed' or new.state not in ('complete','held') or new.kind='account_reconcile' then return new;end if;
 -- These results carry no new primary work. Operation/receipt triggers below
 -- still recover independently when a real financial observation arrives.
 if new.state='complete' and (new.kind in ('customer_updates','customer_attention') or new.outcome in (
  'supply_target_met','updates_disabled','updates_idle','updates_held',
  'attention_disabled','attention_idle','attention_held','waiting_for_daytime_budget',
  'waiting_for_available_credits','seller_inventory_unavailable','waiting_for_active_call',
  'outside_contact_hours','empty','awaiting_conversation','awaiting_counterparty','customer_signature_needed')) then return new;end if;
 changed:=new.state='complete' and new.kind not in ('customer_updates','customer_attention');
 perform icash_work_private.wake_account_followup(new.account_id,changed);
 return new;
end $function$
